@startuml

class City {
  + Name : string
}

class H2SLocation {
  + Address : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Item {
  + Description : string
  + Weight : float
  + Dimensions : string
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class Route {
  + Date : date
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class Employee {
  + Name : string
}

class Article {
  + RFIDTag : string
  + Category : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class Delivery {
  + Date : date
}

City "1" -- "*" H2SLocation
H2SLocation "1" -- "0..1" DistributionCenter
H2SLocation "1" -- "0..1" FoodBank

Resident "1" -- "*" PickupRequest
PickupRequest "1" -- "*" Item

Vehicle "1" -- "*" Route
VolunteerDriver "1" -- "*" Route
Route "1" -- "*" PickupRequest

Item "*" -- "1" Article
Article "*" -- "1" DistributionCenter

Employee "1" -- "*" Article
Employee "1" -- "*" Client : calls

Client "1" -- "*" Delivery
VolunteerDriver "1" -- "*" Delivery

@enduml

